import {
    MeshStandardNodeMaterial,
    MeshBasicNodeMaterial
} from 'three/webgpu';
import {
    uv,
    vec2,
    color,
    float,
    mix,
    smoothstep,
    sub,
    length
} from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as _unused } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
    const {
        Group,
        Mesh,
        PlaneGeometry,
        CylinderGeometry,
        CircleGeometry,
        DirectionalLight,
        Color
    } = ctx.THREE;

    const root = new Group();

    // ---------- Backdrop with vertical gradient ----------
    const backdropGeo = new PlaneGeometry(7, 6);
    const gradientStops = (config.visualSpec && config.visualSpec.gradientStops) || [
        { at: 0, hex: '#0b0b10' },
        { at: 0.55, hex: '#101017' },
        { at: 1, hex: '#16161d' }
    ];
    const uvNode = uv();
    const y = uvNode.y;

    // Linear gradient between three stops
    const gradFirst = mix(
        color(gradientStops[0].hex),
        color(gradientStops[1].hex),
        smoothstep(float(gradientStops[0].at), float(gradientStops[1].at), y)
    );
    const gradientNode = mix(
        gradFirst,
        color(gradientStops[2].hex),
        smoothstep(float(gradientStops[1].at), float(gradientStops[2].at), y)
    );

    const backdropMat = new MeshBasicNodeMaterial({ color: gradientNode });
    const backdrop = new Mesh(backdropGeo, backdropMat);
    backdrop.position.set(0, 0, -2.5);
    root.add(backdrop);

    // ---------- Plinth ----------
    const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 32);
    const plinthMat = new MeshStandardNodeMaterial({
        color: new Color('#14141a'),
        metalness: 0.3,
        roughness: 0.7
    });
    const plinth = new Mesh(plinthGeo, plinthMat);
    // Top face should sit at y = -1.1, so center at -1.225
    plinth.position.y = -1.225;
    root.add(plinth);

    // ---------- Contact shadow ----------
    const shadowGeo = new CircleGeometry(1.6, 32);
    const shadowMat = new MeshBasicNodeMaterial({
        color: new Color('#0b0b10'),
        transparent: true,
        opacity: 0.55,
        depthWrite: false
    });
    const shadow = new Mesh(shadowGeo, shadowMat);
    // Horizontal plane (XZ), rotate to lie flat
    shadow.rotation.x = -Math.PI / 2;
    // Slightly below plinth
    shadow.position.y = -1.3;
    root.add(shadow);

    // ---------- Load Watch GLB ----------
    let loadedGLTF = null;
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
        loadedGLTF = gltf;
        root.add(gltf.scene);
    });

    // ---------- Text Elements ----------
    const textItems = config.textContent ??
        config.intent?.visualSpec?.textContent ??
        [];

    const roleDefaults = {
        headline: { fontSize: 68, offsetY: -1.5 },
        body: { fontSize: 26, offsetY: -1.78 },
        caption: { fontSize: 18, offsetY: -2.0 }
    };

    for (const item of textItems) {
        const role = item.role || 'body';
        const defaults = roleDefaults[role] || roleDefaults.body;
        const fontSize = (item.typography && item.typography.fontSize) || defaults.fontSize;
        const textObj = ctx.fontAtlas.createText(item.text, {
            fontSize,
            color: '#e8ecf2',
            align: 'center'
        });
        textObj.position.set(0, defaults.offsetY, 0);
        root.add(textObj);
    }

    // ---------- Accent Rim Light ----------
    const rimLight = new DirectionalLight('#ff2a38', 0.8);
    rimLight.position.set(-2, 2, 2);
    root.add(rimLight);

    // ---------- Back Rim Light (soft fill) ----------
    const backLight = new DirectionalLight('#e8ecf2', 0.6);
    backLight.position.set(2, -1, -2);
    root.add(backLight);

    // ---------- Cinematic Primitives ----------
    const primitives = [];

    const orbitPrim = ctx.primitives['orbit'](root, {
        speed: 0.15,
        radius: 0.6
    });
    primitives.push(orbitPrim);

    const depthPrim = ctx.primitives['depth-rotate'](root, {
        maxDeg: 6
    });
    primitives.push(depthPrim);

    // ---------- Cleanup ----------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        // Dispose local geometries & materials
        backdropGeo.dispose();
        backdropMat.dispose();

        plinthGeo.dispose();
        plinthMat.dispose();

        shadowGeo.dispose();
        shadowMat.dispose();

        // Dispose GLTF resources if loaded
        if (loadedGLTF && loadedGLTF.scene) {
            loadedGLTF.scene.traverse((obj) => {
                if (obj.isMesh) {
                    if (obj.geometry) obj.geometry.dispose();
                    if (obj.material) {
                        if (Array.isArray(obj.material)) {
                            obj.material.forEach((m) => m.dispose());
                        } else {
                            obj.material.dispose();
                        }
                    }
                }
            });
        }

        // Cleanup primitives
        primitives.forEach((p) => {
            if (p && typeof p.cleanup === 'function') {
                p.cleanup();
            }
        });
    };

    return root;
}
